    short: 'The revolution survives only by spreading. Stand still and it rots.',
    theory: 'Socialism cannot be completed inside one country: a workers’ state isolated in a capitalist world will be strangled from outside or degenerate from within as a bureaucratic caste rises above the class. The revolution must therefore be permanent — uninterrupted at home and carried across borders — and the party must stay answerable to working-class democracy.',
    axes: { econ: -0.9, auth: 0.55, trad: -0.9, intl: 1.0 }, rivals: ['ml', 'mao'],
    econ: { model: 'plan', share: 0.6, eff: 1.03, dist: 0.1 },
    budget: { welfare: 0.16, security: 0.06, science: 0.08, arms: 0.2, heavy: 0.16 },
    control: { type: 'party', body: 'Congress of the Party', auth: 3.0, warVote: 0, cap: 1, lawCost: 12, griev: 0.8 },
    elections: 0,
    recruit: { allowed: ['levee', 'conscription'], def: 'levee' },
    doctrine: { atk: 1.1, def: 0.95, home: 1.0, morale: 'workers', styles: { advance: 1, assault: 1.3, blitz: 1.1, infiltrate: 0.9, siege: 0.8 } },
