    elections: 0,
    recruit: { allowed: ['peoples', 'levee'], def: 'peoples' },
    doctrine: { atk: 0.95, def: 1.15, home: 1.3, morale: 'peasants', styles: { advance: 0.9, assault: 1.2, blitz: 0.55, infiltrate: 1.5, siege: 0.7 } },
    fbase: { workers: 2, peasants: 14, capital: -45, military: 8, clergy: -22, intelligentsia: -14, bureaucracy: 14 },
    fpow: { capital: 0.05, peasants: 1.5, bureaucracy: 1.8, intelligentsia: 0.6, clergy: 0.5 }, ruling: ['peasants', 'bureaucracy'], fnames: { bureaucracy: 'Cadres' },
