    laws: { press: ['free', 'regulated', 'censored'], security: ['liberties', 'police'], land: ['smallholder', 'commune'], labor: ['free', 'control', 'company'], religion: ['tolerance', 'secular'], trade: ['free', 'protect'] },
    lawDef: { press: 'regulated', security: 'police', land: 'smallholder', labor: 'control', religion: 'secular', trade: 'free' },
